GOGHOS.createSarkTestState=function(side='enemy'){
  const sark={front:['sarck'],rear:[]},attackers={front:['char_10','sam','char_06'],rear:[]};
  const s=GOGHOS.createBattleState(side==='player'?sark:attackers,side==='player'?attackers:sark);
  s.log.push('Teste de Steel Jaw · ataque Sark com Raro, Lendário ou Comum para comparar a reação.');
  return s;
}
GOGHOS.createAbilityTestState=function(id){
  if(id==='eletric')return GOGHOS.createBattleState({front:['eletric'],rear:['char_05']},{front:['john','char_03','char_08'],rear:['char_07']});
  if(id==='john')return GOGHOS.createBattleState({front:['john','char_03'],rear:[]},{front:['char_08','char_04'],rear:[]});
  if(id==='penxy')return GOGHOS.createBattleState({front:['penxy','char_06'],rear:[]},{front:['cavaleiro','char_08'],rear:['char_07']});
  if(id==='cavaleiro')return GOGHOS.createBattleState({front:['cavaleiro','char_06'],rear:[]},{front:['ddx'],rear:[]});
  if(id==='zikssy')return GOGHOS.createBattleState({front:['zikssy'],rear:[]},{front:['cavaleiro','char_08'],rear:['char_07']});
  if(id==='elysh') {const s=GOGHOS.createBattleState({front:['elysh','cavaleiro'],rear:[]},{front:['char_03'],rear:[]});s.units.find(u=>u.id==='cavaleiro').hp=80;return s;}
  if(id==='ddx')return GOGHOS.createBattleState({front:['ddx'],rear:[]},{front:['char_03','char_08'],rear:[]});
  if(id==='vaglar')return GOGHOS.createBattleState({front:['vaglar'],rear:[]},{front:['cavaleiro','sarck'],rear:['char_07']});
  throw new Error('Teste de habilidade indisponível.');
}
